package workerpool

import (
	"context"
	"sync"
)

// Job is a unit of work to be processed by the pool.
type Job func(ctx context.Context)

// Pool is a bounded worker pool that processes jobs from a channel.
type Pool struct {
	jobs   chan Job
	wg     sync.WaitGroup
	ctx    context.Context
	cancel context.CancelFunc
}

// New creates a new Pool with the given number of workers.
// The pool does not start processing until Start is called.
func New(numWorkers int) *Pool {
	ctx, cancel := context.WithCancel(context.Background())
	return &Pool{
		jobs:   make(chan Job),
		ctx:    ctx,
		cancel: cancel,
	}
}

// Start launches the specified number of goroutines to process jobs.
// It blocks until all workers have finished (i.e., after Shutdown is called
// and all pending jobs have been processed).
func (p *Pool) Start(numWorkers int) {
	for i := 0; i < numWorkers; i++ {
		p.wg.Add(1)
		go p.worker()
	}
}

